INSERT INTO `tbl_logs` (`id`, `user_id`, `model_id`, `request_data`, `change_attribute`, `method`, `url`, `action`, `controller`, `table_name`, `model_name`, `ip`, `browser`, `os`, `device`, `server`, `record_status`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(31, 3, 4, '{\"_csrf\":\"RUrBHuJlc5tqF6rMBrnzmEQ7cQTyIX4aNBWQjm5kDF4_H4QvjFQKzgtxz6U-47zddUwSbMJ4Knh5YdTrOyw4Ng==\",\"Article\":{\"title\":\"Pagpili ng mga Paitluging Manok\",\"content\":\"<p><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Piliin ang mga dumalagang manok (pullets) na pare-parehas ang edad, kung maaari ay parehas din ang laki, kulay ng balahibo, pangangatawan, malusog, walang sakit o kapansanan at galing sa magagandang lahi ng inahing malusog, palalimlim at may kakayahang mangitlog ng marami. Sa pagpili ng tandang (roosters), kailangang agresibo, malusog at galing sa kawan ng mabilis lumaki o maraming mangitlog na manok.<\\/span><\\/p>\",\"category\":\"Poultry\",\"menu\":\"Chicken\",\"parent_id\":\"1\"}}', '{\"title\":null,\"content\":null,\"category\":null,\"menu\":null,\"parent_id\":null,\"slug\":null,\"record_status\":null,\"created_at\":null,\"updated_at\":null,\"created_by\":null,\"updated_by\":null,\"id\":null}', 'POST', 'http://farmac.local/article/create-content', 'create-content', 'article', 'articles', 'Article', '127.0.0.1', 'Chrome', 'Windows', 'Computer', '{\"REDIRECT_STATUS\":\"200\",\"HTTP_HOST\":\"farmac.local\",\"HTTP_CONNECTION\":\"keep-alive\",\"CONTENT_LENGTH\":\"770\",\"HTTP_CACHE_CONTROL\":\"max-age=0\",\"HTTP_UPGRADE_INSECURE_REQUESTS\":\"1\",\"HTTP_ORIGIN\":\"http:\\/\\/farmac.local\",\"CONTENT_TYPE\":\"application\\/x-www-form-urlencoded\",\"HTTP_USER_AGENT\":\"Mozilla\\/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit\\/537.36 (KHTML, like Gecko) Chrome\\/108.0.0.0 Safari\\/537.36\",\"HTTP_ACCEPT\":\"text\\/html,application\\/xhtml+xml,application\\/xml;q=0.9,image\\/avif,image\\/webp,image\\/apng,*\\/*;q=0.8,application\\/signed-exchange;v=b3;q=0.9\",\"HTTP_REFERER\":\"http:\\/\\/farmac.local\\/article\\/create\\/paraan-ng-pagpaparami-ng-manok?step=content\",\"HTTP_ACCEPT_ENCODING\":\"gzip, deflate\",\"HTTP_ACCEPT_LANGUAGE\":\"en-US,en;q=0.9\",\"HTTP_COOKIE\":\"PHPSESSID=4cgjcf8rcqb43f25msq1gu4spk; _csrf=0407510eac07b15a2e90353ab6c6d9ccc6