INSERT INTO `tbl_logs` (`id`, `user_id`, `model_id`, `request_data`, `change_attribute`, `method`, `url`, `action`, `controller`, `table_name`, `model_name`, `ip`, `browser`, `os`, `device`, `server`, `record_status`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(37, 3, 10, '{\"_csrf\":\"BhKgeyWnPtC3wjPKDcCcGAF9qtA3ATtZPB4rY-ukeqV8R-VKS5ZHhdakVqM1mtNdMArJuAdYbztxam8GvuxOzQ==\",\"Article\":{\"title\":\"Pag-aalaga ng Day-old at Hardened na Sisiw\",\"content\":\"<p>&nbsp;Kailangan nakakulong ang mga sisiw sa kanilang unang 21 na araw at minsanang nakakulong sa loob ng 22-45 na araw.<\\/p>\\r\\n<h4>KULUNGAN<\\/h4>\\r\\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Magpagawa ng Bahay Kuluban (Brooder House) na magbibigay ng proteksyon at komportable sa mga sisiw at magaan sa pagmamaneho sa nagaalaga. Ang mga day-old na sisiw ay madaling makain ng daga at pusa. Tamang pabahay at pag-aalaga ang ibigay sa mga sisiw at mga inahin. Magpatayo ng bahay yari sa mga mura pero matibay na bagay tulad ng scrap na kahoy, kawayan, chicken wire at iba pa.<\\/p>\",\"category\":\"Poultry\",\"menu\":\"Chicken\",\"parent_id\":\"1\"}}', '{\"title\":null,\"content\":null,\"category\":null,\"menu\":null,\"parent_id\":null,\"slug\":null,\"record_status\":null,\"created_at\":null,\"updated_at\":null,\"created_by\":null,\"updated_by\":null,\"id\":null}', 'POST', 'http://farmac.local/article/create-content', 'create-content', 'article', 'articles', 'Article', '127.0.0.1', 'Chrome', 'Windows', 'Computer', '{\"REDIRECT_STATUS\":\"200\",\"HTTP_HOST\":\"farmac.local\",\"HTTP_CONNECTION\":\"keep-alive\",\"CONTENT_LENGTH\":\"899\",\"HTTP_CACHE_CONTROL\":\"max-age=0\",\"HTTP_UPGRADE_INSECURE_REQUESTS\":\"1\",\"HTTP_ORIGIN\":\"http:\\/\\/farmac.local\",\"CONTENT_TYPE\":\"application\\/x-www-form-urlencoded\",\"HTTP_USER_AGENT\":\"Mozilla\\/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit\\/537.36 (KHTML, like Gecko) Chrome\\/108.0.0.0 Safari\\/537.36\",\"HTTP_ACCEPT\":\"text\\/html,application\\/xhtml+xml,application\\/xml;q=0.9,image\\/avif,image\\/webp,image\\/apng,*\\/*;q=0.8,application\\/signed-exchange;v=b3;q=0.9\",\"HTTP_REFERER\":\"http:\\/\\/farmac.local\\/article\\/create\\/paraan-ng-pagpaparami-ng-manok?step=content\",\"HTTP_ACCEPT_ENCODING\":\"gzip, deflate\",\"HTTP