C:\\\\Program Files (x86)\\\\NVIDIA Corporation\\\\PhysX\\\\Common;C:\\\\Program Files\\\\NVIDIA Corporation\\\\NVIDIA NvDLISR;C:\\\\WINDOWS\\\\system32;C:\\\\WINDOWS;C:\\\\WINDOWS\\\\System32\\\\Wbem;C:\\\\WINDOWS\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\;C:\\\\WINDOWS\\\\System32\\\\OpenSSH\\\\;C:\\\\Program Files\\\\nodejs\\\\;C:\\\\Program Files\\\\Git\\\\cmd;C:\\\\ProgramData\\\\ComposerSetup\\\\bin;C:\\\\Program Files\\\\Android\\\\Android Studio\\\\jre\\\\bin;C:\\\\Users\\\\abelg\\\\AppData\\\\Local\\\\Microsoft\\\\WindowsApps;C:\\\\Users\\\\abelg\\\\AppData\\\\Local\\\\GitHubDesktop\\\\bin;C:\\\\Users\\\\abelg\\\\AppData\\\\Roaming\\\\npm;C:\\\\Users\\\\abelg\\\\AppData\\\\Local\\\\Programs\\\\Microsoft VS Code\\\\bin;C:\\\\laragon\\\\bin\\\\php\\\\php-7.4.19-Win32-vc15-x64;C:\\\\Users\\\\abelg\\\\AppData\\\\Roaming\\\\Composer\\\\vendor\\\\bin;C:\\\\Users\\\\abelg\\\\AppData\\\\Local\\\\Android\\\\Sdk\\\\platform-tools\",\"SystemRoot\":\"C:\\\\WINDOWS\",\"COMSPEC\":\"C:\\\\WINDOWS\\\\system32\\\\cmd.exe\",\"PATHEXT\":\".COM;.EXE;.BAT;.CMD;.VBS;.VBE;.JS;.JSE;.WSF;.WSH;.MSC\",\"WINDIR\":\"C:\\\\WINDOWS\",\"SERVER_SIGNATURE\":\"\",\"SERVER_SOFTWARE\":\"Apache\\/2.4.47 (Win64) OpenSSL\\/1.1.1k PHP\\/7.4.19\",\"SERVER_NAME\":\"farmac.local\",\"SERVER_ADDR\":\"127.0.0.1\",\"SERVER_PORT\":\"80\",\"REMOTE_ADDR\":\"127.0.0.1\",\"DOCUMENT_ROOT\":\"C:\\/laragon\\/www\\/farmac\\/web\",\"REQUEST_SCHEME\":\"http\",\"CONTEXT_PREFIX\":\"\",\"CONTEXT_DOCUMENT_ROOT\":\"C:\\/laragon\\/www\\/farmac\\/web\",\"SERVER_ADMIN\":\"admin@example.com\",\"SCRIPT_FILENAME\":\"C:\\/laragon\\/www\\/farmac\\/web\\/index.php\",\"REMOTE_PORT\":\"54002\",\"REDIRECT_URL\":\"\\/article\\/update\\/ibat-ibang-uri-ng-manok\",\"GATEWAY_INTERFACE\":\"CGI\\/1.1\",\"SERVER_PROTOCOL\":\"HTTP\\/1.1\",\"REQUEST_METHOD\":\"POST\",\"QUERY_STRING\":\"\",\"REQUEST_URI\":\"\\/article\\/update\\/ibat-ibang-uri-ng-manok\",\"SCRIPT_NAME\":\"\\/index.php\",\"PHP_SELF\":\"\\/index.php\",\"REQUEST_TIME_FLOAT\":1